// Fecha y pilar rotativo del dia (sin dependencias externas).
const date = new Date().toLocaleDateString('es-BO', { timeZone: 'America/La_Paz' });
const pilares = ['Dolor real (proceso manual que pierde plata/tiempo)','Antes/Despues (negocio sin sistema vs con ONIA, sin metricas falsas)','Caso de uso concreto (chatbot que califica / web que capta / automatizacion que agenda)','Educativo o mito (que si y que no puede la IA para una pyme)','Detras de escena (como ONIA construye)','Autoridad Sergio (fundador joven construyendo el sistema)'];
const dayIdx = Math.floor(Date.now() / 86400000) % pilares.length;
const pilarDelDia = pilares[dayIdx];
return [{ json: { date, pilarDelDia } }];

// Extrae el texto del guion de la respuesta OpenAI-compatible y arma el mensaje.
const j = items[0].json || {};
const content = j.choices && j.choices[0] && j.choices[0].message ? j.choices[0].message.content : '';
const date = new Date().toLocaleDateString('es-BO', { timeZone: 'America/La_Paz' });
let text;
if (!content) {
  text = `ONIA | Guiones ${date}\nNo se pudo generar. Revisar credencial LLM API en n8n o correr la skill guiones-diarios-onia a mano.`;
} else {
  text = `ONIA | Guiones de contenido ${date}\n\n${content}\n\nNada se publica sin tu OK. Para producir: \"Genera Reel ONIA: <tema>\" o \"Flujo carrusel: <slug>\".`;
}
return [{ json: { text: text.slice(0, 3900) } }];
